SELECT p.owner_id, (SELECT coalesce(json_agg(x), '[]'::json) FROM (SELECT id, kind, title, notes, all_day, tz, repeat, repeat_days, repeat_until, remind_min, to_char(starts_at AT TIME ZONE tz, 'YYYYMMDD"T"HH24MISS') AS local_start, to_char(coalesce(ends_at, starts_at + interval '30 minutes') AT TIME ZONE tz, 'YYYYMMDD"T"HH24MISS') AS local_end, to_char(starts_at AT TIME ZONE tz, 'YYYYMMDD') AS local_day, to_char(updated_at AT TIME ZONE 'UTC', 'YYYYMMDD"T"HH24MISS"Z"') AS stamp FROM ys_plan_items WHERE owner_id = p.owner_id AND (repeat IS NOT NULL OR starts_at > now() - interval '60 days') ORDER BY starts_at LIMIT 800) x) AS items, (SELECT coalesce(json_agg(e), '[]'::json) FROM (SELECT ev.id, ev.title, ev.venue, to_char(ev.starts_at AT TIME ZONE 'UTC', 'YYYYMMDD"T"HH24MISS"Z"') AS s, to_char(coalesce(ev.ends_at, ev.starts_at + interval '1 hour') AT TIME ZONE 'UTC', 'YYYYMMDD"T"HH24MISS"Z"') AS e FROM ys_events ev JOIN ys_event_members m ON m.event_id = ev.id AND m.member_id = p.owner_id WHERE ev.starts_at IS NOT NULL AND ev.starts_at > now() - interval '60 days' AND (m.rsvp = 'yes' OR ev.owner_id = p.owner_id) ORDER BY ev.starts_at LIMIT 200) e) AS events FROM ys_plan_prefs p JOIN ys_users u ON u.id = p.owner_id AND u.active WHERE p.feed_token = $1
